import{_ as a,c as r,o as e,ai as i}from"./chunks/framework.BrjRfu4a.js";const c=JSON.parse('{"title":"의의 | 국고채 발행시장 | 한국 국채","description":"국고채는 고정된 원금과 이자가 지급되는 일반적인 형태의 국고채와 원금과 이자가 물가에 연동되는 물가연동국고채 형태로 발행되고 있다.","frontmatter":{"title":"의의 | 국고채 발행시장 | 한국 국채","description":"국고채는 고정된 원금과 이자가 지급되는 일반적인 형태의 국고채와 원금과 이자가 물가에 연동되는 물가연동국고채 형태로 발행되고 있다.","head":[["meta",{"property":"og:title","content":"의의 | 국고채 발행시장 | 한국 국채"}],["meta",{"property":"og:description","content":"국고채는 고정된 원금과 이자가 지급되는 일반적인 형태의 국고채와 원금과 이자가 물가에 연동되는 물가연동국고채 형태로 발행되고 있다."}],["meta",{"property":"og:image","content":"/images/RiskQuantHaun.png"}],["meta",{"property":"og:url","content":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/primary-market/"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/primary-market/"}],["link",{"rel":"alternate","hreflang":"en","href":"https://risk-quant-haun.github.io/korean-treasury-bonds/primary-market/"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/primary-market/"}],["link",{"rel":"canonical","href":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/primary-market/"}]],"date":"2025-03-10T00:00:00.000Z"},"headers":[],"relativePath":"ko/korean-treasury-bonds/primary-market/index.md","filePath":"ko/korean-treasury-bonds/primary-market/index.md"}'),l={name:"ko/korean-treasury-bonds/primary-market/index.md"};function o(n,t,d,s,h,u){return e(),r("div",null,t[0]||(t[0]=[i('<h1 id="🏦-의의" tabindex="-1">🏦 의의 <a class="header-anchor" href="#🏦-의의" aria-label="Permalink to &quot;🏦 의의&quot;">​</a></h1><p><strong>국고채 발행시장 | 한국 국채 | 2025.03.10</strong></p><h2 id="_1️⃣-국고채의-발행-형태" tabindex="-1">1️⃣ 국고채의 발행 형태 <a class="header-anchor" href="#_1️⃣-국고채의-발행-형태" aria-label="Permalink to &quot;1️⃣ 국고채의 발행 형태&quot;">​</a></h2><p>국고채는 고정된 원금과 이자가 지급되는 <strong>일반적인 형태의 국고채</strong>와 원금과 이자가 물가에 연동되는 <strong>물가연동국고채</strong> 형태로 발행되고 있다.</p><h3 id="일반-국고채-만기-구조" tabindex="-1">일반 국고채 만기 구조 <a class="header-anchor" href="#일반-국고채-만기-구조" aria-label="Permalink to &quot;일반 국고채 만기 구조&quot;">​</a></h3><ul><li><strong>2년, 3년, 5년, 10년, 20년, 30년, 50년</strong> 만기 국고채</li></ul><h3 id="물가연동국고채" tabindex="-1">물가연동국고채 <a class="header-anchor" href="#물가연동국고채" aria-label="Permalink to &quot;물가연동국고채&quot;">​</a></h3><ul><li><strong>만기 10년</strong>으로 발행</li></ul><h2 id="_2️⃣-입찰-방식의-정례화" tabindex="-1">2️⃣ 입찰 방식의 정례화 <a class="header-anchor" href="#_2️⃣-입찰-방식의-정례화" aria-label="Permalink to &quot;2️⃣ 입찰 방식의 정례화&quot;">​</a></h2><p>국고채 입찰은 <strong>수요자의 예측성을 제고</strong>하기 위해 정례 실시하며, 각 만기별로 고정된 입찰일을 운영하고 있다:</p><table tabindex="0"><thead><tr><th>만기</th><th>정기 입찰일</th></tr></thead><tbody><tr><td>2년</td><td>매월 첫째 월요일</td></tr><tr><td>3년</td><td>매월 둘째 월요일</td></tr><tr><td>5년</td><td>매월 넷째 월요일</td></tr><tr><td>10년</td><td>매월 셋째 월요일</td></tr><tr><td>20년</td><td>매월 넷째 화요일</td></tr><tr><td>30년</td><td>매월 첫째 화요일</td></tr><tr><td>50년</td><td>매월 둘째 금요일</td></tr><tr><td>물가연동국고채</td><td>격월(짝수월) 첫째 금요일</td></tr></tbody></table><h2 id="_3️⃣-발행-구조와-특성" tabindex="-1">3️⃣ 발행 구조와 특성 <a class="header-anchor" href="#_3️⃣-발행-구조와-특성" aria-label="Permalink to &quot;3️⃣ 발행 구조와 특성&quot;">​</a></h2><h3 id="이표채-형태" tabindex="-1">이표채 형태 <a class="header-anchor" href="#이표채-형태" aria-label="Permalink to &quot;이표채 형태&quot;">​</a></h3><ul><li>국고채는 모두 <strong>표면이자율이 이자지급일에 지급되는 이표채</strong> 형태로 발행</li><li><strong>이자지급주기는 6개월</strong>로 고정</li></ul><h3 id="통합발행제도" tabindex="-1">통합발행제도 <a class="header-anchor" href="#통합발행제도" aria-label="Permalink to &quot;통합발행제도&quot;">​</a></h3><ul><li>국고채는 <strong>통합 발행</strong>되고 있으므로 국고채 입찰일과 관계없이 발행일이 정해짐</li><li>예: 2024년 6월~11월 사이에 발행되는 3년 만기 국고채의 발행일은 2024년 6월 10일로 통일</li><li>최초 이자는 발행일로부터 6개월 후 지급 (위 예시의 경우 2024년 12월 10일)</li></ul><h2 id="_4️⃣-발행계획의-투명성" tabindex="-1">4️⃣ 발행계획의 투명성 <a class="header-anchor" href="#_4️⃣-발행계획의-투명성" aria-label="Permalink to &quot;4️⃣ 발행계획의 투명성&quot;">​</a></h2><h3 id="연간-발행계획" tabindex="-1">연간 발행계획 <a class="header-anchor" href="#연간-발행계획" aria-label="Permalink to &quot;연간 발행계획&quot;">​</a></h3><ul><li><strong>매년 전년도 12월에서 당해 연도 1월</strong> 사이에 발표</li><li>포함 내용: <ul><li>연간 국고채 총 발행물량</li><li>만기물별 발행 비중</li><li>새로 도입되거나 개정되는 주요 정책</li></ul></li></ul><h3 id="월간-발행계획" tabindex="-1">월간 발행계획 <a class="header-anchor" href="#월간-발행계획" aria-label="Permalink to &quot;월간 발행계획&quot;">​</a></h3><ul><li><strong>전월 말일까지 발표</strong> (통상 전월 마지막 목요일)</li><li>포함 내용: <ul><li>신규 발행되거나 바이백 및 교환되는 종목</li><li>입찰일시</li><li>발행 규모</li></ul></li></ul><h2 id="_5️⃣-발행-사무-체계" tabindex="-1">5️⃣ 발행 사무 체계 <a class="header-anchor" href="#_5️⃣-발행-사무-체계" aria-label="Permalink to &quot;5️⃣ 발행 사무 체계&quot;">​</a></h2><p>국고채의 발행, 상환, 교환, 원리금 지급 및 이와 관련된 공고, 입찰, 등록, 상장신청 등 <strong>국고채 발행사무는 국채법에 따라 정부를 대신하여 한국은행이 수행</strong>하고 있다.</p><h3 id="전자화된-발행시스템" tabindex="-1">전자화된 발행시스템 <a class="header-anchor" href="#전자화된-발행시스템" aria-label="Permalink to &quot;전자화된 발행시스템&quot;">​</a></h3><ul><li>국고채 발행사무는 <strong>한국은행 금융결제망(BOK-Wire+)으로 이루어짐</strong></li><li>입찰참가기관인 국고채전문딜러와 예비국고채전문딜러는 BOK-Wire+ 단말기를 이용하여: <ul><li>입찰정보의 조회</li><li>응찰</li><li>낙찰결과 수신 및 확인</li><li>낙찰대금 납부</li><li>등록 신청 등을 수행</li></ul></li></ul><h2 id="_6️⃣-국고채-발행시장의-의의" tabindex="-1">6️⃣ 국고채 발행시장의 의의 <a class="header-anchor" href="#_6️⃣-국고채-발행시장의-의의" aria-label="Permalink to &quot;6️⃣ 국고채 발행시장의 의의&quot;">​</a></h2><p>국고채 발행시장은 <strong>국가재정자금 조달의 핵심적인 수단</strong>이자 <strong>국내 채권시장에서 지표채권(Benchmark) 역할</strong>을 수행하는 중요한 시장이다.</p><p>정부는 <strong>투자자의 예측성을 높이고 효율적이고 안정적인 국고채 발행</strong>을 위해 사전 발행계획 공지, 정례 입찰 실시, 통합발행제도 운영 등 다양한 제도적 기반을 구축하여 운영하고 있다.</p>',28)]))}const g=a(l,[["render",o]]);export{c as __pageData,g as default};
